PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry cumprod_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 batch,
    .param .u32 width
)
{
    // Registers
    .reg .pred   %p<2>;
    .reg .b32    %r<10>;
    .reg .b64    %rd<10>;
    .reg .f32    %f<2>;
    .reg .f16    %h<3>;

    // Load kernel parameters
    ld.param.u64    %rd1, [in_ptr];
    ld.param.u64    %rd2, [out_ptr];
    ld.param.u32    %r1, [batch];
    ld.param.u32    %r2, [width];

    // Compute global thread id: tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32         %r3, %ctaid.x;
    mov.u32         %r4, %ntid.x;
    mov.u32         %r5, %tid.x;
    mad.lo.s32      %r0, %r3, %r4, %r5;        // %r0 = threadId

    // if (threadId >= batch) return;
    setp.ge.u32     %p0, %r0, %r1;
    @%p0           bra DONE;

    // Compute row offset in elements: row_offset = threadId * width
    mul.lo.u32      %r6, %r0, %r2;            // %r6 = row_offset (elements)
    cvt.u64.u32     %rd3, %r6;                // %rd3 = row_offset (bytes, still elements)
    // Convert element offset to byte offset (multiply by 2 for fp16)
    shl.b64         %rd3, %rd3, 1;            // %rd3 = row_offset * 2 (bytes)

    // Pointers to the start of this row
    add.u64         %rd4, %rd1, %rd3;         // %rd4 = in_row_ptr
    add.u64         %rd5, %rd2, %rd3;         // %rd5 = out_row_ptr

    // Initialize accumulator to 1.0 (float32)
    mov.f32         %f0, 1.0;

    // Loop over columns
    mov.u32         %r7, 0;                   // i = 0

LOOP:
    setp.ge.u32     %p1, %r7, %r2;            // if i >= width exit
    @%p1           bra ENDLOOP;

    // byte offset of element i within the row: i * 2
    mul.lo.u32      %r8, %r7, 2;              // %r8 = i*2 (bytes)
    cvt.u64.u32     %rd6, %r8;                // %rd6 = i*2 (bytes)

    // Load input half
    add.u64         %rd7, %rd4, %rd6;         // address of x[i]
    ld.global.f16   %h0, [%rd7];

    // Convert to float32 for accumulation
    cvt.f32.f16     %f1, %h0;
    mul.ftz.f32     %f0, %f0, %f1;            // accumulator *= x[i]

    // Convert accumulator back to half
    cvt.f16.f32     %h1, %f0;

    // Store result
    add.u64         %rd8, %rd5, %rd6;         // address of y[i]
    st.global.f16   [%rd8], %h1;

    // i++
    add.u32         %r7, %r7, 1;
    bra             LOOP;

ENDLOOP:
DONE:
    ret;
}
'''

class ModelNew:
    def __init__(self, dim):
        # dim is fixed to 1 for this implementation
        self.dim = dim
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x):
        assert x.dtype == torch.float16, "Input must be float16"
        y = torch.empty_like(x)
        batch = x.shape[0]
        width = x.shape[1] if x.dim() > 1 else 1

        # Launch configuration: one thread per row
        block = (256, 1, 1)
        grid  = ((batch + block[0] - 1) // block[0], 1, 1)

        args = [
            x.data_ptr(),
            y.data_ptr(),
            batch,
            width
        ]

        ptx_launch(self.module, "cumprod_kernel", grid, block, args)
        return y
